mapper.select:
SELECT p.id, p.email, p.phone, p.created_at
FROM person p
WHERE p.workspace_id = #{workspaceId}
  AND p.id > #{afterId}
  AND p.archived_at IS NULL
  AND p.suspended_at IS NULL
  AND p.provision_ceased_at IS NULL
ORDER BY p.id
LIMIT #{limit}

SELECT c.id, c.website, c.phone, c.created_at
FROM company c
WHERE c.workspace_id = #{workspaceId}
  AND c.id > #{afterId}
  AND c.archived_at IS NULL
ORDER BY c.id
LIMIT #{limit}

SELECT pi.person_id AS record_id, p.name, pi.kind, pi.normalized_value FROM person_identity pi JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id WHERE pi.workspace_id = #{workspaceId} AND pi.kind = #{kind} AND pi.superseded_at IS NULL AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND pi.normalized_value IN
#{normalizedValue}
ORDER BY pi.normalized_value, pi.person_id

SELECT ci.company_id AS record_id, c.name, ci.kind, ci.normalized_value
FROM company_identity ci
JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id
WHERE ci.workspace_id = #{workspaceId}
  AND ci.kind = #{kind}
  AND ci.superseded_at IS NULL
  AND c.archived_at IS NULL
  AND ci.normalized_value IN

    #{normalizedValue}

ORDER BY ci.normalized_value, ci.company_id

WITH ranked_matches AS ( SELECT p.id AS record_id, p.workspace_id AS record_workspace_id, p.name, c.name AS company_name, p.title, NULL AS website, NULL AS industry, pi.kind, pi.normalized_value, ROW_NUMBER() OVER ( PARTITION BY pi.kind, pi.normalized_value ORDER BY CASE WHEN p.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, p.id ) AS match_rank FROM person_identity pi JOIN person p ON p.workspace_id = pi.workspace_id AND p.id = pi.person_id LEFT JOIN company c ON c.id = p.company_id AND c.archived_at IS NULL AND WHERE pi.superseded_at IS NULL AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND AND (
(pi.kind = #{key.kind} AND pi.normalized_value = #{key.normalizedValue})
) ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY kind, normalized_value, record_id

WITH ranked_matches AS ( SELECT c.id AS record_id, c.workspace_id AS record_workspace_id, c.name, NULL AS company_name, NULL AS title, c.website, c.industry, ci.kind, ci.normalized_value, ROW_NUMBER() OVER ( PARTITION BY ci.kind, ci.normalized_value ORDER BY CASE WHEN c.workspace_id = #{workspaceId} THEN 0 ELSE 1 END, c.id ) AS match_rank FROM company_identity ci JOIN company c ON c.workspace_id = ci.workspace_id AND c.id = ci.company_id WHERE ci.superseded_at IS NULL AND c.archived_at IS NULL AND AND (
(ci.kind = #{key.kind} AND ci.normalized_value = #{key.normalizedValue})
) ) SELECT record_id, record_workspace_id, name, company_name, title, website, industry, kind, normalized_value FROM ranked_matches WHERE match_rank <= #{perKeyLimit} ORDER BY kind, normalized_value, record_id

SELECT pi.id
FROM person_identity pi
WHERE pi.workspace_id = #{workspaceId}
  AND pi.kind = #{kind}
  AND pi.normalized_value = #{normalizedValue}
  AND pi.superseded_at IS NULL
ORDER BY pi.person_id, pi.id
FOR UPDATE

SELECT ci.id
FROM company_identity ci
WHERE ci.workspace_id = #{workspaceId}
  AND ci.kind = #{kind}
  AND ci.normalized_value = #{normalizedValue}
  AND ci.superseded_at IS NULL
ORDER BY ci.company_id, ci.id
FOR UPDATE

SELECT id, email, phone, created_at
FROM person
WHERE workspace_id = #{workspaceId}
  AND id = #{personId}
  AND archived_at IS NULL
FOR UPDATE

SELECT id, website, phone, created_at
FROM company
WHERE workspace_id = #{workspaceId}
  AND id = #{companyId}
  AND archived_at IS NULL
FOR UPDATE

mapper.update:
UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'domain'
  AND ci.superseded_at IS NULL
  AND c.archived_at IS NULL
  AND (
    (c.website IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.website AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}

UPDATE company_identity ci
JOIN company c
  ON c.workspace_id = ci.workspace_id
  AND c.id = ci.company_id
SET ci.superseded_at = #{supersededAt}
WHERE ci.workspace_id = #{workspaceId}
  AND ci.company_id = #{companyId}
  AND ci.kind = 'phone'
  AND ci.superseded_at IS NULL
  AND c.archived_at IS NULL
  AND (
    (c.phone IS NULL AND #{rawValue,jdbcType=VARCHAR} IS NULL)
    OR CAST(c.phone AS BINARY) = CAST(#{rawValue,jdbcType=VARCHAR} AS BINARY)
  )

    AND ci.normalized_value <> #{normalizedValue}
